with (root/'sources.csv').open('w', encoding='utf-8', newline='') as f:
    w=csv.writer(f); w.writerow(['id','title','url','type','date','assessment','finding'])
    for sid,title,url,kind,date,assessment,finding,quote in sources:
        w.writerow([sid,title,url,kind,date,assessment,finding])
        quotation = f'\nКороткая цитата: «{quote}»\n' if quote else '\nЦитата не сохранена: использовано содержание и контекст страницы.\n'
        (root/'sources'/f'{sid}.md').write_text(f'# {title}\n\nИсточник: {url}\n\nТип: {kind}. Дата: {date}. Дата проверки: 21.11.2026.\n\nОценка: {assessment}.\n\nНаблюдение: {finding}\n{quotation}\nОграничение: права на воспроизведение материалов проверяются отдельно; материал события или определённой даты не подтверждает нынешнюю ситуацию.\n',encoding='utf-8')
(root/'refresh_targets.md').write_text('''# Что проверять перед следующим этапом

- У дирекции: актуальный план сектора/ряда/места, высоты рядов и препятствия; дата последнего обновления и конфигурация мероприятия.
- Статус модернизации: был ли изменён план после сообщений апреля и октября 2026 года.
- Новые фотографии и видеосъёмка: дата, место съёмки, автор и разрешение на использование.
- Особенности матча и концерта: сцена, временные ограждения, камеры и видимость.
- Пилот: вес загружаемых данных, время до первого вида, FPS и качество на реальных iOS и Android; оценить по фактическим результатам.
- Право использования материалов сторонних организаций и условия конкретных геосервисов.
''',encoding='utf-8')
(root/'findings'/'F1_seat_data.md').write_text('''# Данных для точного вида каждого кресла пока нет

Официальный план показывает группы секторов, но не задаёт координаты и высоту каждого сиденья ([источник 01](../sources/01.md)). Свидетельство о временной площадке в секторе демонстрирует, что препятствия могут зависеть от события ([12](../sources/12.md)). Методика коммерческого поставщика также требует обмеров и проверки по съёмке ([14](../sources/14.md)); источник заинтересован. Эти три свидетельства не являются тремя независимыми замерами стадиона. Вывод о фактической видимости каждого места остаётся недоказанным.
''',encoding='utf-8')
(root/'findings'/'F2_photos.md').write_text('''# Визуальные материалы разных дат

Kazinform снял стадион перед матчем в сентябре 2025 ([03](../sources/03.md)); акимат сообщил об обновлении мест в том же периоде ([04](../sources/04.md)); TengriSport показал отдельное временное состояние после концерта в августе 2026 ([07](../sources/07.md)). Источники подтверждают, что конфигурация и состояние могут меняться; они не подтверждают текущий вид каждого сектора на ноябрь 2026.
''',encoding='utf-8')
(root/'findings'/'F3_rendering.md').write_text('''# Выбор технологии — гипотеза до пилота

Кандидат: лёгкий план + панорама (фото или качественный предрендер). Реалистичность фото относится к точке съёмки, а 3D-рендер зависит от геометрии и проверки. [Поставщик 3DDV](../sources/14.md) описывает свой подход; [Three.js](../sources/15.md) документирует отрисовку повторяющихся объектов. Независимых сопоставимых измерений для этого стадиона нет: претензия «гибрид объективно быстрее и лучше» не подтверждена.
''',encoding='utf-8')
(root/'findings'/'F4_current.md').write_text('''# Реконструкция и старые источники

Операторы сообщали о модернизации как будущем процессе в апреле 2026 ([08](../sources/08.md)); в октябре должностное лицо сообщило об откладывании прежнего проекта расширения ([09](../sources/09.md)). Оба сообщения — передача позиции органов власти средствами СМИ, они не дают полного обследования на ноябрь 2026. Не использовать концепт будущего нового стадиона как изображение существующей арены.
''',encoding='utf-8')
